#[using="Type"] Lemma rauxv_ok_frame : forall m m' B W,
  rauxv_ok m B -> munch W m m' -> wmono rsegs m m' ->
  Forall (fun iv : Z * Z => snd iv <= B /\ (snd iv <= RAUXV_CELL \/ RAUXV_CELL + 8 <= fst iv)) W ->
